# AUTO-GENERATED by _add_compatibility_api.py
"""
궁합 (Compatibility) — 4축 분석 엔진.

Pure engine. No LLM, no language. Deterministic.

Inputs are two semantic profiles (from build_semantic_profile()).
Outputs are tags + scores; content layer maps tags to narrative.

4 axes:
  elements    오행 상생상극 보완성 (complementarity via surplus/deficiency)
  day_master  일간 관계 (stem 合/沖, branch 六合/六沖, ten god)
  ten_gods    십성 모드 정합 (money/work/bonds mode alignment)
  sinsal      신살 공명 (shared special traits)

Overall score is weighted average (day_master > elements > ten_gods > sinsal).
"""
from app.engine.elements import get_ten_god


# ---- element ↔ signature ----
_SIG_BY_ELEM = {"木": "GROWTH", "火": "SPARK", "土": "GROUND", "金": "EDGE", "水": "FLOW"}

# ---- stem relations ----
_STEM_HE = {
    frozenset(["甲", "己"]), frozenset(["乙", "庚"]), frozenset(["丙", "辛"]),
    frozenset(["丁", "壬"]), frozenset(["戊", "癸"]),
}
_STEM_CHONG = {
    frozenset(["甲", "庚"]), frozenset(["乙", "辛"]),
    frozenset(["丙", "壬"]), frozenset(["丁", "癸"]),
}

# ---- branch relations ----
_BRANCH_HE = {
    frozenset(["子", "丑"]), frozenset(["寅", "亥"]),
    frozenset(["卯", "戌"]), frozenset(["辰", "酉"]),
    frozenset(["巳", "申"]), frozenset(["午", "未"]),
}
_BRANCH_CHONG = {
    frozenset(["子", "午"]), frozenset(["丑", "未"]),
    frozenset(["寅", "申"]), frozenset(["卯", "酉"]),
    frozenset(["辰", "戌"]), frozenset(["巳", "亥"]),
}

# ---- ten god favorability (from the day-master perspective) ----
_TG_FAV = {
    "정인": 0.35, "정재": 0.35, "정관": 0.30, "식신": 0.25,
    "편인": 0.15, "편재": 0.20, "편관": 0.10, "상관": 0.10,
    "비견": 0.10, "겁재": -0.05,
}

_TG_CAT = {
    "정인": "TEN_GOD_RESOURCE", "편인": "TEN_GOD_RESOURCE",
    "정재": "TEN_GOD_WEALTH", "편재": "TEN_GOD_WEALTH",
    "정관": "TEN_GOD_OFFICER", "편관": "TEN_GOD_OFFICER",
    "식신": "TEN_GOD_OUTPUT", "상관": "TEN_GOD_OUTPUT",
    "비견": "TEN_GOD_FRIEND", "겁재": "TEN_GOD_FRIEND",
}

# ---- mode compatibility ----
_MODE_COMPLEMENT = {
    frozenset(["THE_CREATOR", "THE_OFFICER"]),
    frozenset(["THE_CREATOR", "THE_MENTOR"]),
    frozenset(["THE_CHALLENGER", "THE_OFFICER"]),
    frozenset(["THE_SURVIVOR", "THE_MENTOR"]),
    frozenset(["THE_MYSTIC", "THE_OFFICER"]),
    frozenset(["THE_OPERATOR", "THE_STEWARD"]),
    frozenset(["THE_OPERATOR", "THE_MENTOR"]),
    frozenset(["THE_FLOW", "THE_STEWARD"]),
}
_MODE_TENSION = {
    frozenset(["THE_OPERATOR", "THE_SURVIVOR"]),
    frozenset(["THE_CHALLENGER", "THE_CREATOR"]),
}


def _grade(score: float) -> str:
    if score >= 0.7:
        return "PEAK"
    if score >= 0.4:
        return "FAVORABLE"
    if score >= -0.4:
        return "NEUTRAL"
    if score >= -0.7:
        return "CAUTION"
    return "CHALLENGING"


# ---- axis 1: elements ----
def _axis_elements(pa: dict, pb: dict) -> dict:
    a_pct = pa["energy_signature"]["percentages"]
    b_pct = pb["energy_signature"]["percentages"]

    support_ab = 0.0
    support_ba = 0.0
    tension = 0.0

    for elem in ("木", "火", "土", "金", "水"):
        a = a_pct.get(elem, 0.0) / 100.0
        b = b_pct.get(elem, 0.0) / 100.0
        # A surplus feeds B deficiency
        if a >= 0.25 and b <= 0.10:
            support_ab += min(a * 0.8, 0.4)
        # B surplus feeds A deficiency
        elif b >= 0.25 and a <= 0.10:
            support_ba += min(b * 0.8, 0.4)
        # Both overload
        if a >= 0.30 and b >= 0.30:
            tension += 0.20

    score = max(-1.0, min(1.0, support_ab + support_ba - tension))
    if score >= 0.4:
        tag = "COMPLEMENTARY"
    elif score >= 0.1:
        tag = "BALANCED"
    elif score >= -0.2:
        tag = "MODERATE"
    else:
        tag = "TENSION"

    return {
        "score": round(score, 2),
        "grade": _grade(score),
        "tag": tag,
        "support_ab": round(support_ab, 2),
        "support_ba": round(support_ba, 2),
        "tension": round(tension, 2),
    }


# ---- axis 2: day master ----
def _axis_day_master(pa: dict, pb: dict) -> dict:
    a_stem = pa["archetype"]["stem"]
    b_stem = pb["archetype"]["stem"]
    a_pillar = pa["pillars"].get("day_pillar", "")
    b_pillar = pb["pillars"].get("day_pillar", "")
    a_branch = a_pillar[1] if isinstance(a_pillar, str) and len(a_pillar) == 2 else None
    b_branch = b_pillar[1] if isinstance(b_pillar, str) and len(b_pillar) == 2 else None

    stem_pair = frozenset([a_stem, b_stem])

    if stem_pair in _STEM_HE:
        base = 0.55
        tag = "STEM_UNION"
    elif stem_pair in _STEM_CHONG:
        base = -0.35
        tag = "STEM_CLASH"
    else:
        tg_ab = get_ten_god(a_stem, b_stem)
        tg_ba = get_ten_god(b_stem, a_stem)
        base = (_TG_FAV.get(tg_ab, 0.0) + _TG_FAV.get(tg_ba, 0.0)) / 2
        tag = _TG_CAT.get(tg_ab, "MIXED")

    branch_note = None
    if a_branch and b_branch:
        bp = frozenset([a_branch, b_branch])
        if bp in _BRANCH_HE:
            base += 0.25
            if tag not in ("STEM_UNION", "STEM_CLASH"):
                tag = "BRANCH_UNION"
            branch_note = "BRANCH_UNION"
        elif bp in _BRANCH_CHONG:
            base -= 0.25
            if tag not in ("STEM_UNION", "STEM_CLASH"):
                tag = "BRANCH_CLASH"
            branch_note = "BRANCH_CLASH"

    score = max(-1.0, min(1.0, base))
    return {
        "score": round(score, 2),
        "grade": _grade(score),
        "tag": tag,
        "branch_note": branch_note,
    }


# ---- axis 3: ten gods (mode alignment) ----
def _mode_score(a: str, b: str) -> tuple:
    if a == b:
        if a in ("THE_CREATOR", "THE_MENTOR", "THE_GENERALIST"):
            return 0.15, "SAME_MODE"
        return 0.05, "SAME_MODE"
    pair = frozenset([a, b])
    if pair in _MODE_COMPLEMENT:
        return 0.45, "COMPLEMENTARY"
    if pair in _MODE_TENSION:
        return -0.15, "TENSION"
    return 0.05, "NEUTRAL"


def _axis_ten_gods(pa: dict, pb: dict) -> dict:
    scores, tags = [], []
    for mode_key in ("money_mode", "work_mode", "bond_mode"):
        s, t = _mode_score(pa[mode_key], pb[mode_key])
        scores.append(s)
        tags.append(t)

    score = round(sum(scores) / len(scores), 2)
    if "COMPLEMENTARY" in tags:
        tag = "COMPLEMENTARY"
    elif all(t == "SAME_MODE" for t in tags):
        tag = "MIRROR"
    elif "TENSION" in tags:
        tag = "TENSION"
    else:
        tag = "NEUTRAL"

    return {
        "score": score,
        "grade": _grade(score),
        "tag": tag,
        "breakdown": {
            "money": tags[0],
            "work": tags[1],
            "bonds": tags[2],
        },
    }


# ---- axis 4: sinsal ----
def _axis_sinsal(pa: dict, pb: dict) -> dict:
    a_traits = set(pa.get("special_traits", []))
    b_traits = set(pb.get("special_traits", []))
    shared = a_traits & b_traits

    if not a_traits and not b_traits:
        return {"score": 0.0, "grade": "NEUTRAL", "tag": "NEITHER", "shared": []}

    if shared:
        if "MAGNETIC_DRAW" in shared:
            return {"score": 0.45, "grade": "FAVORABLE",
                     "tag": "SHARED_ATTRACTION", "shared": sorted(shared)}
        if "SOLITARY_DEPTH" in shared:
            return {"score": 0.50, "grade": "FAVORABLE",
                     "tag": "SHARED_DEPTH", "shared": sorted(shared)}
        if "RESTLESS_FEET" in shared:
            return {"score": 0.30, "grade": "FAVORABLE",
                     "tag": "SHARED_WANDER", "shared": sorted(shared)}
        if "COMMANDER" in shared:
            return {"score": 0.15, "grade": "NEUTRAL",
                     "tag": "SHARED_LEADERSHIP", "shared": sorted(shared)}
        return {"score": 0.30, "grade": "FAVORABLE",
                 "tag": "SHARED_RESONANCE", "shared": sorted(shared)}

    if a_traits and b_traits:
        return {"score": 0.20, "grade": "NEUTRAL", "tag": "OPPOSITE_PULL", "shared": []}

    return {"score": 0.10, "grade": "NEUTRAL", "tag": "SINGLE_ANCHOR", "shared": []}


# ---- public API ----
def compute_compatibility(pa: dict, pb: dict) -> dict:
    elements = _axis_elements(pa, pb)
    day_master = _axis_day_master(pa, pb)
    ten_gods = _axis_ten_gods(pa, pb)
    sinsal = _axis_sinsal(pa, pb)

    weights = {"elements": 0.30, "day_master": 0.35, "ten_gods": 0.20, "sinsal": 0.15}
    overall_score = round(
        elements["score"] * weights["elements"]
        + day_master["score"] * weights["day_master"]
        + ten_gods["score"] * weights["ten_gods"]
        + sinsal["score"] * weights["sinsal"],
        2,
    )

    return {
        "axes": {
            "elements": elements,
            "day_master": day_master,
            "ten_gods": ten_gods,
            "sinsal": sinsal,
        },
        "overall": {
            "score": overall_score,
            "grade": _grade(overall_score),
        },
    }
